void MainWindow::slotShowErrorStatus(const QString &status)
{
    QMessageBox::warning(this, "警告", status, QMessageBox::Ok);
    if("打开设备失败，请重试！" == status)
    {
        ui->actionOpenDevice->setEnabled(true);
        ui->actionCloseDevice->setEnabled(false);
    }
}

void MainWindow::slotChangeConnectStatus()
{
    if(ui->actionOpenDevice->isEnabled())
    {
        ui->actionOpenDevice->setEnabled(false);
        ui->actionCloseDevice->setEnabled(true);
        slotStartMesTest();
    }
    else
    {

        ui->actionOpenDevice->setEnabled(true);
        ui->actionCloseDevice->setEnabled(false);
        QMessageBox::information(this, "提示", "请先连接CAN卡\n", QMessageBox::Ok);
    }
}

void MainWindow::slotCloseCAN()
{
    signalCloseCAN();
}

void MainWindow::slotChangeItemBeforeFinish()
{
    QMessageBox::warning(this, "警告", "上一项测试尚未完成\n请完成上一项测试后再进行下一项", QMessageBox::Ok);
}

void MainWindow::slotStartTest1()
{
    ifSuccess1 = true;
    emit signalSetGD(ui->gdComboBox->currentText());
    QColor color;
    color.setRgb(0, 0, 0, 255);
    emit signalSetSoft(ui->lineEdit->text());
    emit signalSetHard(ui->lineEdit_2->text());
    for(int i = 0; i < 29; i++)
    {
        if(ui->tableWidget->item(i, 2))
        {
            ui->tableWidget->item(i, 2)->setTextColor(color);
            if(ui->tableWidget->item(i, 2)->text() == "测试通过" || ui->tableWidget->item(i, 2)->text() == "测试未通过")
            {
                ui->tableWidget->item(i, 2)->setText("待测试");
            }
        }
        if(ui->tableWidget->item(i, 3))
        {
            ui->tableWidget->item(i, 3)->setText("");
        }
    }
    qDebug() << "start test1";
    t11 = std::chrono::high_resolution_clock::now();
    t01 = std::chrono::high_resolution_clock::now();

    if(checkBoxs1.at(0)->isChecked())
    {
        currentItem1 = TestSetBatteryVoltage;
        testTimer1->start(1000);
    }
    else
    {
        currentItem1 = StartTest;
        slotContinue1();
    }
    QPixmap *pix = new QPixmap(":/image/loading.png");
    QSize sz(400, 400);
    ui->statusLabel->setPixmap(pix->scaled(sz));
    ui->tabWidget->tabBar()->setTabTextColor(0, QColor(0, 0, 0));
}

