void MainWindow::slotFinish1()
{
    if(currentItem1 >= 2)
    {
        QColor color;
        color.setRgb(0, 200, 80, 255);
        if(ui->tableWidget->item((int)currentItem1 - 2, 2))
        {
            ui->tableWidget->item((int)currentItem1 - 2, 2)->setTextColor(color);
            ui->tableWidget->item((int)currentItem1 - 2, 2)->setText("测试通过");
        }
    }
    qDebug() << "signal finish1 as " << currentItem1;
    slotContinue1();
}

