void MainWindow::slotReceiveGDList(const QStringList &list)
{
    QCollator collator;
    collator.setNumericMode(true); // 数字模式
    collator.setCaseSensitivity(Qt::CaseInsensitive);
    QStringList tempList = list;
    std::sort(tempList.begin(),
              tempList.end(),
              [&](const QString& a, const QString& b)
              {
                  return collator.compare( a, b ) > 0;
              });
    ui->gdComboBox->addItems(tempList);
    ui->gdButton->setEnabled(false);

    QSettings setting(QDir::currentPath() + "/version.ini", QSettings::IniFormat);
    QString gd = setting.value("gd").toString();
    ui->gdComboBox->setCurrentIndex(ui->gdComboBox->findText(gd));
    ui->getVerisonButton->setEnabled(true);
    QTimer::singleShot(100, this, [=]()
    {
        slotOpenConnPage();
    });
}

void MainWindow::slotResult(bool result)
{
    if(result)
    {
        QMessageBox::information(this, "提示", "上传MES成功！\n", QMessageBox::Ok);
    }
    else
    {
        QMessageBox::information(this, "提示", "上传MES失败，请重试！\n", QMessageBox::Ok);
    }
}

void MainWindow::slotGetVersion(const QString &hard, const QString &soft)
{
    qDebug() << "receive soft verison as " << soft << " and hard verison as " << hard;
    if(hard == "" )
    {
        QMessageBox::information(this, "提示", "硬件版本未空，请检查！\n", QMessageBox::Ok);
    }
    if(soft == "")
    {
        QMessageBox::information(this, "提示", "软件版本未空，请检查！\n", QMessageBox::Ok);
    }
    ui->lineEdit->setText(soft);
    ui->lineEdit_2->setText(hard);
    qDebug() << "start test";

    emit signalSendTester(ui->operatorEdit->text());
    emit signalSetSoft(ui->lineEdit->text());
    emit signalSetHard(ui->lineEdit_2->text());
    ui->macEdit->setEnabled(false);
    ui->serialEdit->setEnabled(false);
    ui->gdComboBox->setEnabled(false);
    ui->operatorEdit->setEnabled(false);
    ui->gzLineEdit->setEnabled(false);
    ui->gdComboBox->setEnabled(false);
    QPixmap *pix = new QPixmap(":/image/loading.png");
    QSize sz(400, 400);
    ui->statusLabel->setPixmap(pix->scaled(sz));
}

void MainWindow::slotChangeUI()
{
    if(ui->tableWidget->isVisible())
    {
        ui->tableWidget->hide();
        ui->groupBox->hide();
        ui->statusLabel->show();
    }
    else
    {
        ui->tableWidget->show();
        ui->groupBox->show();
    }
}

void MainWindow::slotShowVersion()
{
    QString temp = APP_VERSION;
    QMessageBox::information(this, "提示", "软件版本为" + temp, QMessageBox::Ok);
}

