void MainWindow::slotSetModFail1()
{
    ifSuccess1 = false;
    ui->labelTime->setText("0");
    QPixmap *pix = new QPixmap(":/image/fail.png");
    QSize sz(400, 400);
    ui->statusLabel->setPixmap(pix->scaled(sz));
    testresult1.insert("TestResult", "fail");
    emit signalTestResult1(false);
    ui->progressBar->show();
    ui->progressBar->setValue(100);
    ui->processLabel->show();
    QMessageBox::warning(this, "警告", "1号待测板设置工装模式失败！", QMessageBox::Ok);
}

